    id, actor_user_id, action, entity_type, entity_id, before_summary, after_summary
)
VALUES (
    #{id}, #{actorId}, #{action}, 'PRICE_RULE', #{entityId},
    CAST(#{beforeSummary} AS jsonb),
    jsonb_build_object(
        'ruleCode', #{after.ruleCode}, 'version', #{after.version},
