INSERT INTO quote (
    id, quote_no, move_request_id, version_no, status,
    subtotal_amount, discount_amount, tax_amount, total_amount,
    currency, calculation_snapshot, issued_at, expires_at
)
VALUES (
    #{id}, #{quoteNo}, #{requestId}, #{version}, 'ISSUED',
    #{subtotal}, #{discount}, #{tax}, #{total}, 'KRW',
    jsonb_build_object(
        'carryingDistanceMeters', #{conditions.carryingDistanceMeters},
        'floorCount', #{conditions.floorCount},
        'additionalPipingMeters', #{conditions.additionalPipingMeters},
        'taxRatePercent', #{taxRate}
    ),
    #{issuedAt}, #{expiresAt}
)

mapper.update:
UPDATE quote
SET calculation_snapshot = calculation_snapshot || jsonb_build_object(
    'appliedRules',
    COALESCE((
        SELECT jsonb_agg(rule_snapshot ORDER BY id)
        FROM quote_line
        WHERE quote_id = #{quoteId}
    ), '[]'::jsonb)
)
WHERE id = #{quoteId}

UPDATE move_request
SET status = 'QUOTED', updated_at = now()
WHERE id = #{requestId}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM move_request
    WHERE id = #{requestId} AND customer_id = #{customerId}
)

SELECT id, quote_no, version_no, status, currency, subtotal_amount,
       discount_amount, tax_amount, total_amount, issued_at, expires_at
FROM quote
WHERE move_request_id = #{requestId}
ORDER BY version_no DESC
LIMIT #{limit} OFFSET #{offset}

SELECT quote_id, line_code, description, quantity, unit_price, line_amount FROM quote_line WHERE quote_id IN
#{quoteId}
ORDER BY quote_id, id

mapper.update:
UPDATE quote
SET status = 'EXPIRED', updated_at = now()
WHERE move_request_id = #{requestId} AND status = 'ISSUED' AND id <> #{quoteId}

UPDATE quote
SET status = 'ACCEPTED', updated_at = now()
WHERE id = #{quoteId}
